const V13_RULES_VERSION='1.0';
function v13Text(){return V13_RULES[currentLanguage]||V13_RULES.en}
function v13RulesHTML(){
 const t=v13Text();
 return `<div class="policyBox sc-unified-rules">
   <h3>${t.title}</h3>
   <ul>${t.items.map(x=>`<li>${x}</li>`).join('')}</ul>
 </div>
 <label class="sc-ack"><input type="checkbox" id="v13RulesAck" onchange="v13ToggleSubmit()"><span>${t.ack}</span></label>`;
}
function openV13Rules(){
 const candidates=[...document.querySelectorAll('button,a,div')];
 const el=candidates.find(x=>/Good to Know|Reservation.*Rules|Kurallar|Правил|Hausregeln|règles|规则/i.test((x.textContent||'').trim()) && typeof x.onclick==='function');
 if(el){el.click();return}
 alert((ARRIVAL_POLICY&&ARRIVAL_POLICY[currentLanguage])||ARRIVAL_POLICY.en);
}
function v13FindSubmit(){
 return [...document.querySelectorAll('button')].find(b=>/submit|send request|reservation request|rezervasyon.*gönder|отправ|senden|envoyer|提交/i.test(b.textContent||''));
}
function v13ToggleSubmit(){
 const b=v13FindSubmit(),c=document.getElementById('v13RulesAck'); if(!b||!c)return;
 const legacy=document.getElementById('policyAgree');
 if(legacy)legacy.checked=c.checked;
 b.disabled=!c.checked;b.classList.toggle('sc-submit-disabled',!c.checked);
}
function v13InstallRules(){
 const b=v13FindSubmit(); if(!b)return;
 if(!document.getElementById('v13RulesBlock')){
   const wrap=document.createElement('div');
   wrap.id='v13RulesBlock';
   wrap.innerHTML=v13RulesHTML();
   b.parentNode.insertBefore(wrap,b);
 }
 v13ToggleSubmit();
}
function v13CaptureAcceptance(r){
 const c=document.getElementById('v13RulesAck');
 if(c&&c.checked){
   r.houseRulesAccepted=true;r.houseRulesAcceptedAt=new Date().toISOString();r.houseRulesVersion=V13_RULES_VERSION;
 }
}
function v13RefreshProfessionalText(){
 const t=v13Text();
 const h=document.getElementById('hotelNotifyHint'); if(h)h.textContent=t.notify;
 const o=document.getElementById('outsideNotifyHint'); if(o)o.textContent=t.notify;
 const m=document.getElementById('v13MyReservationsDesc'); if(m)m.textContent=t.myDesc;
 const block=document.getElementById('v13RulesBlock');
 if(block){
   const wasChecked=!!document.getElementById('v13RulesAck')?.checked;
   block.innerHTML=v13RulesHTML();
   const c=document.getElementById('v13RulesAck');
   if(c)c.checked=wasChecked;
   v13ToggleSubmit();
 }
 const ext=document.getElementById('v13ExternalNote');
 if(ext){ext.innerHTML='<b>'+t.externalTitle+'</b><br>'+t.externalText;}
}
function v13ExternalEntry(){
 const p=new URLSearchParams(location.search);
 if(p.get('source')!=='instagram'&&p.get('guest')!=='outside')return;
 const t=v13Text();
 let d=document.getElementById('v13ExternalNote');
 if(!d){
   d=document.createElement('div');
   d.id='v13ExternalNote';
   d.className='sc-external-note';
   const target=document.querySelector('.container,.wrap,main')||document.body;
   target.insertBefore(d,target.firstChild);
 }
 d.innerHTML='<b>'+t.externalTitle+'</b><br>'+t.externalText;
 setGuestType('outside');
}
function v13DeepLink(){
 const p=new URLSearchParams(location.search);
 const ref=(p.get('reservation')||'').trim();
 if(!ref)return;
 localStorage.setItem('sushiClubDeepLinkReservation',ref);
 setTimeout(()=>{
   const db=loadDB();
   const r=db.reservations.find(x=>String(x.requestId||'')===ref||String(x.id)===ref);
   if(r)rememberMyReservation(r.id);
   show('myReservations');
   setTimeout(()=>{
     const list=document.getElementById('myReservationList');
     if(!list)return;
     const card=[...list.querySelectorAll('.card')].find(c=>(c.textContent||'').includes(ref));
     if(card){
       card.style.outline='1px solid var(--gold,#A88E60)';
       card.scrollIntoView({block:'center'});
     }
   },100);
 },200);
}

