function today(){return new Date().toISOString().slice(0,10)}
function loadDB(){
  const base={reservations:[],blocked:{},slotCapacity:44,tableCapacity:16,tableGroups:[
  {area:'Indoor', seats:4, count:4},
  {area:'Indoor', seats:2, count:3},
  {area:'Terrace', seats:2, count:7},
  {area:'Terrace', seats:4, count:2}
]};
  try{
    const db=Object.assign(base,JSON.parse(localStorage.getItem('sushiClubReservationsDemo')||'{}'));
    (db.reservations||[]).forEach(r=>{if(r.status==='late_cancelled')r.status='cancelled';});
    return db;
  }catch(e){return base}
}
function saveDB(db){localStorage.setItem('sushiClubReservationsDemo',JSON.stringify(db))}
function tableGroups(){
  const db=loadDB();
  return Array.isArray(db.tableGroups)&&db.tableGroups.length?db.tableGroups:[
  {area:'Indoor', seats:4, count:4},
  {area:'Indoor', seats:2, count:3},
  {area:'Terrace', seats:2, count:7},
  {area:'Terrace', seats:4, count:2}
];
}
function tableInventory(){
  const arr=[];
  tableGroups().forEach(g=>{for(let i=0;i<Number(g.count||0);i++)arr.push(Number(g.seats||0))});
  return arr.filter(x=>x>0).sort((a,b)=>a-b);
}
function capacity(){return tableInventory().reduce((a,b)=>a+b,0)||Number(loadDB().slotCapacity||44)}
function confirmedGuests(date,time){
  return loadDB().reservations.filter(r=>r.date===date&&r.time===time&&['confirmed','reconfirmed'].includes(r.status))
    .reduce((sum,r)=>sum+Number(r.guests||0),0)
}
function slotBlocked(date,time){
  const db=loadDB();
  return !!(db.blocked[date]&&db.blocked[date][time]);
}
function allocateParty(inventory,party){
  const inv=inventory.slice().sort((a,b)=>a-b), p=Number(party||1);
  const single=inv.findIndex(x=>x>=p);
  if(single>=0){inv.splice(single,1);return inv}
  let sum=0; const used=[];
  for(let i=inv.length-1;i>=0&&sum<p;i--){sum+=inv[i];used.push(i)}
  if(sum<p)return null;
  used.sort((a,b)=>b-a).forEach(i=>inv.splice(i,1));
  return inv;
}
function remainingInventory(date,time){
  let inv=tableInventory();
  const rows=loadDB().reservations.filter(r=>r.date===date&&r.time===time&&['confirmed','reconfirmed'].includes(r.status))
    .sort((a,b)=>Number(b.guests)-Number(a.guests));
  for(const r of rows){const next=allocateParty(inv,r.guests);if(next===null)return [];inv=next}
  return inv;
}
function slotCanFitParty(date,time,party=1){
  if(slotBlocked(date,time))return false;
  return allocateParty(remainingInventory(date,time),Number(party||1))!==null;
}
function slotFull(date,time,party=1){return !slotCanFitParty(date,time,party)}

document.querySelectorAll('#reserveTimes .time').forEach(b=>{
  b.onclick=()=>{
    if(b.disabled)return;
    document.querySelectorAll('#reserveTimes .time').forEach(x=>x.classList.remove('active'));
    b.classList.add('active');
    syncSelectedTime();
  }
});
document.getElementById('rdate').value=today();
document.getElementById('rdate').min=today();
document.getElementById('staffDate').value=today();

['rdate','guests'].forEach(id=>document.getElementById(id).addEventListener('change',renderGuestTimes));

function renderGuestTimes(){
  const date=document.getElementById('rdate').value||today();
  const party=Number(document.getElementById('guests').value||1);
  let firstAvailable=null;
  document.querySelectorAll('#reserveTimes .time').forEach(b=>{
    const unavailable=slotBlocked(date,b.innerText)||slotFull(date,b.innerText,party);
    b.disabled=unavailable;
    b.style.opacity=unavailable?'.35':'1';
    b.style.cursor=unavailable?'not-allowed':'pointer';
    if(unavailable)b.classList.remove('active');
    if(!unavailable&&!firstAvailable)firstAvailable=b;
  });
  if(!document.querySelector('#reserveTimes .time.active')&&firstAvailable)firstAvailable.classList.add('active');
  syncSelectedTime();
}


let guestType='hotel';
function setGuestType(type){
  guestType=type;
  document.getElementById('hotelGuestBtn').classList.toggle('active',type==='hotel');
  document.getElementById('outsideGuestBtn').classList.toggle('active',type==='outside');
  document.getElementById('hotelGuestPanel').style.display=type==='hotel'?'block':'none';
  document.getElementById('outsideGuestPanel').style.display=type==='outside'?'block':'none';
}
function syncSelectedTime(){
  const a=document.querySelector('#reserveTimes .time.active:not(:disabled)');
  const x=document.getElementById('selectedTimeText');
  if(x)x.textContent=a?a.innerText:msg('pleaseSelect');
}

function confirmReservation(){
  const rulesCheckbox=document.getElementById('v13RulesAck');
  if(!rulesCheckbox || !rulesCheckbox.checked){
    alert(msg('agreePolicy'));
    return;
  }
  const name=document.getElementById('rname').value.trim();
  const date=document.getElementById('rdate').value;
  const guests=Number(document.getElementById('guests').value);
  const active=document.querySelector('#reserveTimes .time.active:not(:disabled)');
  const room=guestType==='hotel'?document.getElementById('rroom').value.trim():'';
  const hotelContact=document.getElementById('hotelContact').value.trim();
  const outsidePhone=document.getElementById('outsidePhone').value.trim();
  const outsideEmail=document.getElementById('outsideEmail').value.trim();
  const email=guestType==='outside'?outsideEmail:'';
  const contact=guestType==='hotel'?hotelContact:outsidePhone;
  const request=document.getElementById('rrequest').value.trim();
  const db=loadDB();

  if(!name||!date||!guests||guests<1||!active){
    alert(msg('mainRequired'));
    return;
  }
  if(guestType==='hotel' && !room){
    alert(msg('enterRoom'));
    return;
  }
  if(guestType==='outside' && !outsidePhone && !outsideEmail){
    alert(msg('enterOutsideContact'));
    return;
  }
  const existingActive=db.reservations.find(r=>{
    if(!['pending','confirmed','reconfirmed'].includes(r.status)||r.date!==date||r.time!==active.innerText)return false;
    if(guestType==='hotel')return r.guestType==='hotel'&&String(r.room||'').trim()===room;
    return r.guestType==='outside'&&(
      (outsidePhone&&String(r.contact||'').trim()===outsidePhone)||
      (outsideEmail&&String(r.email||'').trim().toLowerCase()===outsideEmail.toLowerCase())
    );
  });
  if(existingActive){
    alert(msg('duplicate'));
    rememberMyReservation(existingActive.id);refreshMyHome();show('myReservations');return;
  }
  const time=active.innerText;
  const requestId='SC-'+String(Date.now()).slice(-6);
  if(slotBlocked(date,time)||slotFull(date,time,guests)){
    alert(msg('unavailable'));
    renderGuestTimes(); return;
  }

  const newReservation={
    id:Date.now(),requestId,date,time,guests,originalGuests:guests,name,guestType,room,email,contact,request,status:'pending',createdAt:new Date().toISOString(),audit:[{type:'CREATED',when:new Date().toLocaleString(),text:'Reservation created for '+guests+' guest(s)'}]
  };
  v13CaptureAcceptance(newReservation);
  db.reservations.unshift(newReservation);
  saveDB(db);
  rememberMyReservation(newReservation.id);
  refreshMyHome();

  document.getElementById('successTitle').innerText=msg('sentTitle');
  document.getElementById('successText').innerText=msg('sentText');
  document.getElementById('summary').innerHTML=
    '<b>'+escapeHtml(msg('request'))+' '+requestId+'</b><br><br>'+
    '<b>'+escapeHtml(msg('leadGuest'))+':</b> '+escapeHtml(name)+'<br>'+
    '<b>'+escapeHtml(msg('dateTime'))+':</b> '+date+' · '+time+'<br>'+
    '<b>'+escapeHtml(msg('partySize'))+':</b> '+guests+' '+escapeHtml(guestWord(guests))+'<br>'+
    '<b>'+escapeHtml(msg('guestType'))+':</b> '+escapeHtml(guestType==='hotel'?msg('hotelGuest'):msg('outsideGuest'))+
    (room?'<br><b>'+escapeHtml(msg('room'))+':</b> '+escapeHtml(room):'')+
    (contact?'<br><b>'+escapeHtml(msg('contact'))+':</b> '+escapeHtml(contact):'')+
    (email?'<br><b>'+escapeHtml(msg('email'))+':</b> '+escapeHtml(email):'')+
    '<br><b>'+escapeHtml(msg('specialRequest'))+':</b> '+(request?escapeHtml(request):escapeHtml(msg('none')))+
    '<br><br><span style="font-size:11px;color:#777">'+msg('exactParty',{n:guests,guestWord:guestWord(guests)})+'</span>';
  show('success');
}


/* v11 My Reservations */
function myReservationIds(){
  try{return JSON.parse(localStorage.getItem('sushiClubMyReservationIds')||'[]').map(Number)}catch(e){return []}
}
function rememberMyReservation(id){
  const ids=myReservationIds();
  if(!ids.includes(Number(id))) ids.unshift(Number(id));
  localStorage.setItem('sushiClubMyReservationIds',JSON.stringify(ids.slice(0,20)));
}
function myReservations(){
  const ids=myReservationIds(),db=loadDB();
  return db.reservations.filter(r=>ids.includes(Number(r.id))).sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time));
}
function isManageable(r){return !['cancelled','late_cancelled','rejected','no_show','completed','declined'].includes(r.status)}
function refreshMyHome(){
  const rows=myReservations().filter(r=>isManageable(r));
  const count=document.getElementById('myCount'),txt=document.getElementById('myHomeText');
  const c=MY_CARD_LANG[currentLanguage]||MY_CARD_LANG.en;
  const eyebrow=document.getElementById('myBookingEyebrow');
  const title=document.getElementById('myBookingTitle');
  const button=document.getElementById('myBookingButton');
  if(eyebrow)eyebrow.textContent=c.eyebrow;
  if(title)title.textContent=c.title;
  if(button)button.textContent=c.button;
  if(count)count.textContent=rows.length;
  if(txt)txt.textContent=rows.length
    ? (rows.length===1?msg('activeCountOne'):msg('activeCountMany',{n:rows.length}))
    : c.empty;
}
function bookingCard(r,canManage=true){
  const n=Number(r.guests||0);
  return `<div class="booking-card">
    <div class="booking-head">
      <div><div class="booking-ref">${escapeHtml(r.requestId||msg('reservation'))}</div><div class="booking-name">${escapeHtml(r.name||msg('guest'))}</div></div>
      <span class="booking-status ${r.status}">${escapeHtml(statusText(r.status))}</span>
    </div>
    <div class="booking-meta"><b>${r.date} · ${r.time}</b><br>
      ${n} ${escapeHtml(guestWord(n))}${r.room?' · '+escapeHtml(msg('room'))+' '+escapeHtml(r.room):''}<br>
      ${escapeHtml(msg('specialRequest'))}: ${r.request?escapeHtml(r.request):escapeHtml(msg('none'))}
    </div>
    ${canManage&&isManageable(r)?`<div class="booking-actions"><button onclick="editMyReservation(${r.id})">${escapeHtml(msg('edit'))}</button><button onclick="cancelMyReservation(${r.id})">${escapeHtml(msg('cancel'))}</button></div>`:''}
  </div>`;
}
function renderMyReservations(){
  const rows=myReservations(),box=document.getElementById('myReservationList');
  box.innerHTML=rows.length?rows.map(r=>bookingCard(r,true)).join(''):`<div class="card"><p class="smallnote">${escapeHtml(msg('noBooking'))}</p></div>`;
}
function cancelMyReservation(id){
  const db=loadDB(),r=db.reservations.find(x=>Number(x.id)===Number(id));
  if(!r||!isManageable(r))return alert(msg('cannotCancel'));
  if(!confirm(msg('confirmCancel')))return;
  const diffHours=(new Date(r.date+'T'+r.time+':00')-new Date())/3600000;
  const old=r.status;
  r.status='cancelled';
  r.audit=r.audit||[];
  r.audit.push({type:'GUEST CANCELLATION',when:new Date().toLocaleString(),text:`Status ${old} → ${r.status}`});
  r.notificationQueue=r.notificationQueue||[];
  r.notificationQueue.push({type:'GUEST_CANCELLATION',createdAt:new Date().toISOString(),status:'pending',deepLink:'?reservation='+encodeURIComponent(r.requestId||r.id)});
  saveDB(db);renderMyReservations();refreshMyHome();
}
let guestEditingId=null;
function editMyReservation(id){
  const db=loadDB(),r=db.reservations.find(x=>Number(x.id)===Number(id));
  if(!r||!isManageable(r))return alert(msg('cannotEdit'));
  guestEditingId=Number(id);
  document.getElementById('guestEditRef').textContent=(r.requestId||msg('reservation'))+' · '+msg('currentStatus')+': '+statusText(r.status);
  document.getElementById('geDate').value=r.date||today();
  document.getElementById('geDate').min=today();
  document.getElementById('geTime').innerHTML=TIMES.map(t=>`<option value="${t}" ${t===r.time?'selected':''}>${t}</option>`).join('');
  document.getElementById('geGuests').value=r.guests||1;
  document.getElementById('geName').value=r.name||'';
  document.getElementById('geRoom').value=r.room||'';
  document.getElementById('gePhone').value=r.contact||'';
  document.getElementById('geEmail').value=r.email||'';
  document.getElementById('geRequest').value=r.request||'';
  document.getElementById('guestEditOverlay').style.display='flex';
}
function closeGuestEdit(){document.getElementById('guestEditOverlay').style.display='none';guestEditingId=null}
function saveGuestEdit(){
  const db=loadDB(),r=db.reservations.find(x=>Number(x.id)===Number(guestEditingId));if(!r)return;
  const next={
    date:document.getElementById('geDate').value,
    time:document.getElementById('geTime').value,
    guests:Number(document.getElementById('geGuests').value),
    name:document.getElementById('geName').value.trim(),
    room:document.getElementById('geRoom').value.trim(),
    contact:document.getElementById('gePhone').value.trim(),
    email:document.getElementById('geEmail').value.trim(),
    request:document.getElementById('geRequest').value.trim()
  };
  if(!next.date||!TIMES.includes(next.time)||!next.guests||next.guests<1||!next.name)return alert(msg('requiredEdit'));
  if(r.guestType==='hotel'&&!next.room)return alert(msg('roomRequired'));
  if(r.guestType==='outside'&&!next.contact&&!next.email)return alert(msg('outsideContactRequired'));

  const changes=[];
  const labels={date:'Date',time:'Time',guests:'Party size',name:'Lead guest',room:'Room',contact:'Phone',email:'E-mail',request:'Special request'};
  Object.keys(next).forEach(k=>{
    const before=String(r[k]??''),after=String(next[k]??'');
    if(before!==after)changes.push(`${labels[k]} ${before||'—'} → ${after||'—'}`);
  });
  if(!changes.length){closeGuestEdit();return}

  const requiresReconfirm = String(r.date)!==String(next.date)||String(r.time)!==String(next.time)||Number(r.guests)!==Number(next.guests);
  Object.assign(r,next);
  if(requiresReconfirm)r.status='pending';
  r.audit=r.audit||[];
  r.audit.push({type:'GUEST EDIT',when:new Date().toLocaleString(),text:changes.join(' · ')});
  r.notificationQueue=r.notificationQueue||[];
  r.notificationQueue.push({type:'GUEST_EDIT',createdAt:new Date().toISOString(),status:'pending',deepLink:'?reservation='+encodeURIComponent(r.requestId||r.id)});
  saveDB(db);closeGuestEdit();renderMyReservations();refreshMyHome();renderGuestTimes();
  alert(requiresReconfirm?msg('editPending'):msg('editUpdated'));
}
function normalizeBookingIdentity(v){return String(v||'').toLowerCase().replace(/\s+/g,'').replace(/[()+\-]/g,'')}
function findReservation(){
  const ref=document.getElementById('findRef').value.trim().toUpperCase();
  const identity=normalizeBookingIdentity(document.getElementById('findIdentity').value);
  const result=document.getElementById('findResult'),db=loadDB();
  const r=db.reservations.find(x=>String(x.requestId||'').toUpperCase()===ref);
  if(!r){result.innerHTML='<div class="smallnote">'+escapeHtml(msg('notFound'))+'</div>';return}
  const valid=[r.room,r.contact,r.email].map(normalizeBookingIdentity).filter(Boolean);
  if(!identity||!valid.includes(identity)){result.innerHTML='<div class="smallnote">'+escapeHtml(msg('detailsMismatch'))+'</div>';return}
  rememberMyReservation(r.id);refreshMyHome();
  result.innerHTML=bookingCard(r,true);
}

function setStaffTab(tab){
  staffTab=tab;
  ['requests','timeline','availability'].forEach(x=>{
    document.getElementById('staff'+x[0].toUpperCase()+x.slice(1)+'Panel').style.display=x===tab?'block':'none';
    document.getElementById('staffTab'+x[0].toUpperCase()+x.slice(1)).classList.toggle('active',x===tab);
  });
  renderStaff();
}

function renderStaff(){
  const date=document.getElementById('staffDate').value||today();
  document.getElementById('staffDate').value=date;
  const filter=document.getElementById('staffFilter').value;
  const db=loadDB();
  document.getElementById('slotCapacity').value=db.slotCapacity||20;

  const all=db.reservations.filter(r=>r.date===date);
  const shown=filter==='all'?all:all.filter(r=>r.status===filter);
  const pending=all.filter(r=>r.status==='pending').length;
  const confirmed=all.filter(r=>r.status==='confirmed').length;
  const confirmedPax=all.filter(r=>r.status==='confirmed').reduce((a,r)=>a+Number(r.guests||0),0);

  document.getElementById('staffStats').innerHTML=
    `<div class="staff-stat"><b>${all.length}</b><span>Total</span></div>
     <div class="staff-stat"><b>${pending}</b><span>Pending</span></div>
     <div class="staff-stat"><b>${confirmed}</b><span>Confirmed</span></div>
     <div class="staff-stat"><b>${confirmedPax}</b><span>Guests</span></div>`;

  document.getElementById('staffRequests').innerHTML=shown.length?shown.map(r=>`
    <div class="staff-request">
      <div class="request-top"><b>${r.time} · ${escapeHtml(r.name)}</b><span class="pill ${r.status}">${r.status}</span></div>
      <div class="meta">${r.guests} guest(s)${r.room?' · Room '+escapeHtml(r.room):''}${r.contact?' · '+escapeHtml(r.contact):''}${r.email?' · '+escapeHtml(r.email):''}${r.request?'<br>'+escapeHtml(r.request):''}</div>
      ${r.status==='pending'?`<div class="staff-actions"><button class="confirmBtn" onclick="setStatus(${r.id},'confirmed')">CONFIRM</button><button class="declineBtn" onclick="setStatus(${r.id},'rejected')">DECLINE</button></div>`:''}
    </div>`).join(''):'<p class="desc" style="margin:0">No reservations in this view.</p>';

  document.getElementById('staffSlots').innerHTML=TIMES.map(t=>{
    const blocked=slotBlocked(date,t), count=confirmedGuests(date,t), cap=capacity();
    return `<div class="slot-row"><div class="slot-time">${t}</div><div class="slot-info">${blocked?'Closed for new reservations':count+' / '+cap+' confirmed guests'}</div><button class="slot-button ${blocked?'open':''}" onclick="toggleSlot('${date}','${t}')">${blocked?'OPEN':'BLOCK'}</button></div>`;
  }).join('');

  document.getElementById('staffTimeline').innerHTML=TIMES.map(t=>{
    const rows=all.filter(r=>r.time===t&&r.status!=='rejected');
    const count=confirmedGuests(date,t), cap=capacity(), pct=Math.min(100,(count/cap)*100);
    return `<div class="timeline-card">
      <div class="timeline-top"><div class="timeline-time">${t}</div><div class="timeline-count">${slotBlocked(date,t)?'BLOCKED':count+' / '+cap+' guests'}</div></div>
      <div class="capacity-bar"><span style="width:${pct}%"></span></div>
      ${rows.length?rows.map(r=>`<div class="timeline-booking"><b>${escapeHtml(r.name)}</b> · ${r.guests} guest(s) · <span class="pill ${r.status}">${r.status}</span></div>`).join(''):'<div class="meta">No reservations</div>'}
    </div>`;
  }).join('');
}

function setStatus(id,status){
  const db=loadDB(), r=db.reservations.find(x=>x.id===id);
  if(!r)return;
  if(status==='confirmed' && (slotBlocked(r.date,r.time)||slotFull(r.date,r.time,r.guests))){
    alert('This slot does not have enough demo capacity. Open the slot or adjust the capacity first.');
    return;
  }
  r.status=status; saveDB(db); renderStaff(); renderGuestTimes();
}
function toggleSlot(date,time){
  const db=loadDB(); db.blocked[date]=db.blocked[date]||{};
  db.blocked[date][time]=!db.blocked[date][time];
  saveDB(db); renderStaff(); renderGuestTimes();
}
function saveCapacity(){
  const db=loadDB(), value=Number(document.getElementById('slotCapacity').value);
  if(!value||value<1)return alert('Enter a valid capacity.');
  db.slotCapacity=value; saveDB(db); renderStaff(); renderGuestTimes();
}
function escapeHtml(v){return String(v||'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}

